===api.ts===
import { getJson, postJson } from '../../api/http';

// An invoice as the API exposes it — an amount belonging to a project. The query key is scoped to
// the project, ['invoices', projectId], so each project's detail page reads (and invalidates) only
// its own invoices: the list reads the key, the add form invalidates it.
export type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};
export type NewInvoice = { projectId: number; amount: number };

// The base key for a project's invoices. The list query appends its current sort below it, so the
// 'id' and 'due' orderings cache separately — while a write still invalidates ['invoices', id] and,
// by prefix, refreshes whichever ordering is on screen.
export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;

// How to order the list: earliest-due-first ('due') or id order (the default). The server reads the
// same `sort` key, so the ordering is applied once, at the source, not re-sorted on the client.
export type InvoiceSort = 'id' | 'due';

export const listInvoices = (projectId: number, sort: InvoiceSort = 'id'): Promise<Invoice[]> =>
  getJson<Invoice[]>(`/api/invoices?projectId=${projectId}&sort=${sort}`);

// One invoice, with its status WORKED OUT from its payments (still owing / part paid / paid). The
// detail page reads this to show the derived status; it is recomputed server-side from the payments.
export const getInvoice = (invoiceId: number): Promise<Invoice> =>
  getJson<Invoice>(`/api/invoices/one?invoiceId=${invoiceId}`);

export const createInvoice = (body: NewInvoice): Promise<Invoice> =>
  postJson<Invoice>('/api/invoices', body);

// Send an invoice — flips DRAFT -> SENT server-side and appends the audit record. Callers invalidate
// ['invoices', projectId] on success so the invoices panel (and the row actions) refetch the status.
export const sendInvoice = (id: number): Promise<Invoice> =>
  postJson<Invoice>('/api/invoices/send', { id });

// Cancel an invoice sent by mistake — flips it to VOID server-side and appends the audit record. A
// VOID invoice stops counting towards what is owed. Callers invalidate ['invoices', projectId] (and
// ['dashboard']) on success so the invoices panel and the home figures refetch.
export const cancelInvoice = (id: number): Promise<Invoice> =>
  postJson<Invoice>('/api/invoices/cancel', { id });
===invoices.slot===
import { useQuery } from '@tanstack/react-query';
import { ProjectDetail } from '../../slots/defs/projectDetail';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { invoicesKey, listInvoices, type Invoice, type InvoiceSort } from './api';
import { formatMoney } from '../../ui/money';
import { useSearchParam, asString } from '../../url/useSearchParam';

// The project's invoices and what they add up to — one panel filling the project.detail region.
// Reads server data under ['invoices', projectId] (never copied into state); the add form shares
// the key, so a successful add refreshes this with no import between them. The total is DERIVED
// from the same query (never stored), and amounts render with two decimals.
function ProjectInvoices({ projectId }: { projectId: number }) {
  // The ordering lives in the URL under the shared `invoiceSort` key — the sort control writes it,
  // this list reads it. It is part of the query key, so each ordering caches on its own and the
  // server returns the rows already sorted.
  const [sortParam] = useSearchParam('invoiceSort', asString);
  const sort: InvoiceSort = sortParam === 'due' ? 'due' : 'id';
  const { data: invoices } = useQuery({
    queryKey: [...invoicesKey(projectId), sort],
    queryFn: () => listInvoices(projectId, sort),
  });

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <>
      <table data-testid="project-invoices-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th>Status</th>
            <th>Issued</th>
            <th>Due</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((invoice: Invoice) => (
            <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
              <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
              <td data-testid="invoice-status">{invoice.status}</td>
              <td data-testid="invoice-issued">{invoice.issuedDate}</td>
              <td data-testid="invoice-due">{invoice.dueDate}</td>
              <td>
                <InvoiceRow.Slot invoiceId={invoice.id} projectId={projectId} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p data-testid="project-invoices-total">{formatMoney(total)}</p>
    </>
  );
}

export const contribution = ProjectDetail.fill({ order: 20, Component: ProjectInvoices });
===dueApi===
import { getJson } from '../../api/http';

// How much is still left to pay on one invoice after any payments — what the API exposes for the
// outstanding balance. The query key is scoped to the invoice, ['invoice-due', invoiceId], so each
// row reads (and would invalidate) only its own balance.
export type InvoiceDue = {
  invoiceId: number;
  amountDue: number;
};

// The key for one invoice's outstanding balance. The row's due-amount cell reads it; a successful
// payment invalidates it (shared with the payments key by prefix is not needed — the pay/record
// forms invalidate this key directly) so the balance refetches, with no import between panels.
export const invoiceDueKey = (invoiceId: number) => ['invoice-due', invoiceId] as const;

